import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden rounded-full border border-transparent px-2 py-0.5 text-xs font-medium whitespace-nowrap transition-colors focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 [&>svg]:pointer-events-none [&>svg]:size-3",
  {
    // Variants + states from Figma "Badge" (23:995).
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        // Chip fill is `--chip`, its own token: #efefeb light, #2a2f37 dark.
        // NOT `--secondary` (#cad1db light), which reads as a heavy block on the
        // white content layer, and not a borrowed surface token either — the
        // value light wants is `--background`, which is #080808 in dark and would
        // render chips near-black. `--secondary` stays as it is because it also
        // fills secondary BUTTONS, which need the weight.
        secondary:
          "bg-chip text-secondary-foreground hover:bg-chip/80",
        outline:
          "border-border text-foreground hover:bg-accent hover:text-accent-foreground",
        ghost: "text-foreground hover:bg-accent hover:text-accent-foreground",
        // soft tint — red @10% bg + red text (DS, not a solid fill)
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:ring-destructive/20",
        // verified — fixed DS blue + BadgeCheck icon (pass as child)
        verified: "bg-verified text-verified-foreground hover:bg-verified/90",
        link: "text-primary underline-offset-4 hover:underline",
        // Pastel fills — one pair per hue, same in both themes. Applications
        // bind meaning to a hue; the DS only ships the hues. See index.css.
        "pastel-blue":
          "bg-pastel-blue text-pastel-blue-foreground hover:bg-pastel-blue/90",
        "pastel-amber":
          "bg-pastel-amber text-pastel-amber-foreground hover:bg-pastel-amber/90",
        "pastel-violet":
          "bg-pastel-violet text-pastel-violet-foreground hover:bg-pastel-violet/90",
        "pastel-rose":
          "bg-pastel-rose text-pastel-rose-foreground hover:bg-pastel-rose/90",
        "pastel-slate":
          "bg-pastel-slate text-pastel-slate-foreground hover:bg-pastel-slate/90",
        "pastel-teal":
          "bg-pastel-teal text-pastel-teal-foreground hover:bg-pastel-teal/90",
        "pastel-green":
          "bg-pastel-green text-pastel-green-foreground hover:bg-pastel-green/90",
      },
      /**
       * Geometry, independent of colour.
       *   pill — the default badge.
       *   disc — a 16px circle carrying one or two characters (a "code disc").
       *          Prefer the CodeDisc component over `shape="disc"` directly: it
       *          enforces the tooltip + aria-label that stop the letter being
       *          the only carrier of meaning.
       */
      shape: {
        pill: "",
        /* 22px, NOT 16. The letter moved from 9px to the DS's 12px step, and
           the circle moved with it: 16 x (12/9) is 21.3, and 22 keeps the same
           proportion the disc has always had — "EM", the widest code, is 18.1px
           at this size and fills 82% of the circle, against 85% before. At 20
           it would have had less than a pixel of air on each side. */
        disc: "size-5.5 justify-center rounded-full p-0 text-xs font-semibold",
      },
    },
    defaultVariants: {
      variant: "default",
      shape: "pill",
    },
  }
)

function Badge({
  className,
  variant = "default",
  shape = "pill",
  asChild = false,
  ...props
}: React.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot.Root : "span"

  return (
    <Comp
      data-slot="badge"
      data-variant={variant}
      data-shape={shape}
      className={cn(badgeVariants({ variant, shape }), className)}
      {...props}
    />
  )
}

const badgeNumberVariants = cva(
  "inline-flex h-5 min-w-5 shrink-0 items-center justify-center rounded-full px-1 text-xs font-medium tabular-nums transition-colors",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground",
        secondary: "bg-chip text-secondary-foreground",
        outline: "border border-border text-foreground",
        ghost: "text-foreground",
        destructive: "bg-destructive/10 text-destructive",
        verified: "bg-verified text-verified-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  }
)

export interface BadgeNumberProps
  extends Omit<React.ComponentProps<"span">, "children">,
    VariantProps<typeof badgeNumberVariants> {
  count: number
  /** Numbers above `max` render as `max+` (e.g. 99+). */
  max?: number
}

/** Circular count badge — Figma "Badge Number" (17100:10130). */
function BadgeNumber({
  className,
  variant = "default",
  count,
  max = 99,
  ...props
}: BadgeNumberProps) {
  const label = count > max ? `${max}+` : String(count)
  return (
    <span
      data-slot="badge-number"
      data-variant={variant}
      className={cn(badgeNumberVariants({ variant }), className)}
      {...props}
    >
      {label}
    </span>
  )
}

export { Badge, badgeVariants, BadgeNumber, badgeNumberVariants }

import { Badge } from "@/components/ui/badge";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/** Pastel hues a code disc can take. The DS ships hues; callers bind meaning. */
export type CodeDiscTone =
  | "pastel-blue"
  | "pastel-amber"
  | "pastel-violet"
  | "pastel-rose"
  | "pastel-slate"
  | "pastel-teal"
  | "pastel-green";

export interface CodeDiscProps {
  /** One or two characters shown in the disc, e.g. "D". */
  code: string;
  /**
   * What the code means, e.g. "Delivery". Required, and used twice: as the
   * tooltip and as the `aria-label`. The letter alone must never be the only
   * carrier of meaning — sighted users get the tooltip, screen readers get the
   * label, and neither has to decode the initial.
   */
  label: string;
  tone?: CodeDiscTone;
  className?: string;
}

/**
 * Code disc — a 22px pastel circle carrying an initial, with the full word on
 * hover/focus. Use where a repeated category has to sit inside a dense row and
 * a full pill would not fit (table cells, list rows).
 *
 * The geometry is `Badge shape="disc"`; this wrapper exists to make the
 * accessible label non-optional, which a bare Badge cannot enforce.
 *
 * ```tsx
 * <CodeDisc code="D" label="Delivery" tone="pastel-blue" />
 * <CodeDisc code="E" label="Extraction" tone="pastel-amber" />
 * ```
 */
export function CodeDisc({
  code,
  label,
  tone = "pastel-blue",
  className,
}: CodeDiscProps) {
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          {/* Badge renders a span, so tabIndex makes the tooltip reachable by
              keyboard as well as by pointer. */}
          <Badge
            variant={tone}
            shape="disc"
            aria-label={label}
            tabIndex={0}
            className={className}
          >
            {code}
          </Badge>
        </TooltipTrigger>
        <TooltipContent>{label}</TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

/**
 * A TYPE AS A PILL (Pavan, 2026-10-16 — the Sales orders table's Type pill,
 * everywhere a TABLE shows a type). The disc's hue, carried over, so a type
 * keeps its colour between the board card's disc and the table's pill.
 */
export const discTonePill = (tone: CodeDiscTone): import("@/components/ui/pill").PillColor =>
  (
    {
      "pastel-slate": "grey",
      /* NOT RED (Pavan, 2026-10-16): red is for a warning, and a type is not
         one — the rose disc's pill is pink. */
      "pastel-rose": "pink",
      "pastel-violet": "violet",
      "pastel-blue": "blue",
      "pastel-amber": "orange",
      "pastel-teal": "cyan",
      "pastel-green": "green",
    } as Record<string, import("@/components/ui/pill").PillColor>
  )[tone] ?? "grey";

"use client"

import * as React from "react"
import { Tooltip as TooltipPrimitive } from "radix-ui"

import { cn } from "@/lib/utils"

function TooltipProvider({
  delayDuration = 0,
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Provider>) {
  return (
    <TooltipPrimitive.Provider
      data-slot="tooltip-provider"
      delayDuration={delayDuration}
      {...props}
    />
  )
}

function Tooltip({
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Root>) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />
}

function TooltipTrigger({
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Trigger>) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />
}

function TooltipContent({
  className,
  sideOffset = 0,
  children,
  ...props
}: React.ComponentProps<typeof TooltipPrimitive.Content>) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-slot="tooltip-content"
        sideOffset={sideOffset}
        className={cn(
          "z-50 w-fit origin-(--radix-tooltip-content-transform-origin) animate-in rounded-md bg-foreground px-3 py-1.5 text-xs text-balance text-background fade-in-0 zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95",
          className
        )}
        {...props}
      >
        {children}
        <TooltipPrimitive.Arrow className="z-50 size-2.5 translate-y-[calc(-50%_-_2px)] rotate-45 rounded-[2px] bg-foreground fill-foreground" />
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  )
}

export { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider }

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/** Merge conditional class names and de-dupe Tailwind utilities. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
